/**
 * Inserts original bindings into the result, uses ?__rowIdx to resolve original bindings. See
 * {@link org.eclipse.rdf4j.query.algebra.evaluation.federation.ServiceJoinIterator} and {@link SPARQLFederatedService}.
 *
 * @author Andreas Schwarte
 */
public class ServiceJoinConversionIteration extends ConvertingIteration<BindingSet, BindingSet> {

	protected final List<BindingSet> bindings;

	private final String rowIndexVar;

	public ServiceJoinConversionIteration(CloseableIteration<BindingSet> iter,
			List<BindingSet> bindings) {
		this(iter, bindings, "__rowIdx");
	}

	ServiceJoinConversionIteration(CloseableIteration<BindingSet> iter, List<BindingSet> bindings,
			String rowIndexVar) {
		super(new FilterIteration<BindingSet>(iter) {
			@Override
			protected boolean accept(BindingSet remote) {
				BindingSet input = bindings.get(getRowIndex(remote, rowIndexVar));
				// The control column is not a binding returned by the SERVICE expression.
				if (input.hasBinding(rowIndexVar)) {
					SPARQLQueryBindingSet withoutRowIndex = new SPARQLQueryBindingSet(input);
					withoutRowIndex.removeBinding(rowIndexVar);
					input = withoutRowIndex;
				}
				return QueryResults.bindingSetsCompatible(input, remote);
			}

			@Override
			protected void handleClose() {
			}
		});
		this.bindings = bindings;
		this.rowIndexVar = rowIndexVar;
	}

	@Override
	protected BindingSet convert(BindingSet bIn) throws QueryEvaluationException {

		BindingSet input = bindings.get(getRowIndex(bIn, rowIndexVar));
		SPARQLQueryBindingSet res = new SPARQLQueryBindingSet(bIn.size() + input.size());
		for (Binding binding : bIn) {
			if (!rowIndexVar.equals(binding.getName()) && binding.getValue() != null) {
				res.addBinding(binding);
			}
		}
		for (Binding binding : input) {
			if (binding.getValue() != null && !res.hasBinding(binding.getName())) {
				res.addBinding(binding);
			}
		}
		return res;
	}

	private static int getRowIndex(BindingSet result, String rowIndexVar) {
		Value rowIndex = result.getValue(rowIndexVar);
		// should never occur: in such case we would have to create the cross product (which
		// is dealt with in another place)
		if (rowIndex == null) {
			throw new QueryEvaluationException(
					"Invalid join. Probably this is due to non-standard behavior of the SPARQL endpoint. "
							+ "Please report to the developers.");
		}
		return Integer.parseInt(rowIndex.stringValue());
	}
}
